// Request from the admin's "Otestovať" button: one restaurant (not necessarily saved yet)
const body = $input.first().json.body || {};
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Bratislava', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const menuDate = /^\d{4}-\d{2}-\d{2}$/.test(String(body.menu_date || '')) ? body.menu_date : today;
return [{
  json: {
    source_id: String(body.source_id || 'test').slice(0, 60),
    source_name: String(body.source_name || 'Test').slice(0, 120),
    source_type: String(body.source_type || ''),
    source_url: String(body.source_url || ''),
    parser_name: String(body.parser_name || ''),
    parser_config: body.parser_config && typeof body.parser_config === 'object' ? body.parser_config : {},
    has_weekend_menu: body.has_weekend_menu === true,
    menu_date: menuDate,
    run_id: `test-${menuDate}-${Math.random().toString(36).slice(2, 8)}`,
    timeoutMs: 15000,
    maxItems: 100,
  },
}];

// Small JSON for the admin: what the parser found, nothing is written to the DB
const r = $input.first().json;
const items = (r.menuItems || []).map((i) => ({ menu_code: i.menu_code, category: i.category, title: i.title, description: i.description, price_eur: i.price_eur, allergens: i.allergens }));
return [{ json: { ok: r.status === 'success', status: r.status || 'failed', itemCount: items.length, items, errorCode: r.errorCode || null, errorMessage: r.errorMessage || null, debug: (r.debugDayLines || []).slice(0, 40) } }];

const row = $input.first().json;
const message = typeof row.error === 'string' ? row.error : row.error?.message || row.message || 'Parser workflow zlyhal';
return [{ json: { ok: false, status: 'failed', itemCount: 0, items: [], errorCode: 'PARSER_WORKFLOW_ERROR', errorMessage: String(message).slice(0, 500) } }];
